134	import org.springframework.web.server.ResponseStatusException;
135	
136	/**
137	 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
138	 * missing note is stored empty.
139	 */
140	@Service
141	public class ClaimService {
142	
143	    private final ClaimRepository claims;
144	    private final PersonRepository people;
145	    private final RateService rates;
146	    private final SheetService sheets;
147	    private final Audit audit;
148	
149	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
150	            Audit audit) {
151	        this.claims = claims;
152	        this.people = people;
153	        this.rates = rates;
154	        this.sheets = sheets;
155	        this.audit = audit;
156	    }
157	
158	    @Transactional(readOnly = true)
159	    public List<Claim> list(String sheetId) {
160	        return claims.findBySheetIdOrderByIdDesc(sheetId);
161	    }
162	
163	    @Transactional
164	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
165	        sheets.load(sheetId, user);
166	        Person person = people.findByIdAndSheetId(personId, sheetId)
167	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
168	        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount),
169	                date != null ? date : sheets.today(sheetId), note != null ? note : ""));
170	        record("CLAIM_ADDED", user, person, claim);
171	        return claim;
172	    }
173	
174	    @Transactional
175	    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note) {
176	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
177	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
178	        claim.setAmount(scaled(amount));
179	        claim.setDate(date != null ? date : sheets.today(sheetId));
180	        claim.setNote(note != null ? note : "");
181	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
182	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
183	        record("CLAIM_EDITED", user, person, claim);
184	        return claim;
185	    }
186	
187	    /**
188	     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
189	     * gives the claim the sheet's next number; voiding clears it (the number is not given again).
190	     * Opening records who opened it; that user cannot settle it (403).
191	     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date.
192	     */
193	    @Transactional
194	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
195	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers.
196	        Sheet sheet = next == ClaimStatus.OPEN
197	                ? sheets.lock(sheetId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"))
198	                : null;
199	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
200	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
201	        if (!claim.getStatus().canBecome(next)) {
202	            throw new ResponseStatusException(HttpStatus.CONFLICT,
203	                    "A " + claim.getStatus() + " claim cannot become " + next);
204	        }
205	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
206	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
207	        }
208	        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
209	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
210	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
211	        claim.setStatus(next);
212	        claim.setNumber(next == ClaimStatus.VOID ? null : number);
213	        if (next == ClaimStatus.OPEN) {
214	            claim.setOpenedBy(user);
215	        }
216	        List<String> extra = new ArrayList<>();
217	        if (next == ClaimStatus.SETTLED) {
218	            BigDecimal due = rates.inForce(sheetId, person.getGrade(), claim.getDate())
219	                    .map(rate -> claim.getAmount().multiply(rate.getRate())
220	                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
221	                    .orElse(null);
222	            claim.setSettledDue(due);
223	            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
224	        }
225	        record(switch (next) {
226	            case OPEN -> "CLAIM_OPENED";
227	            case SETTLED -> "CLAIM_SETTLED";
228	            case VOID -> "CLAIM_VOIDED";
229	            case DRAFT -> throw new IllegalStateException();
230	        }, user, person, claim, number, extra);
231	        return claim;
232	    }
233	
234	    private void record(String event, String user, Person person, Claim claim) {
235	        record(event, user, person, claim, claim.getNumber(), List.of());
236	    }
237	
238	    /**
239	     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number
240	     * (or, when voided, the number it had) adds number=&lt;number&gt;; any extra fields follow it.
241	     */
242	    private void record(String event, String user, Person person, Claim claim, Long number, List<String> extra) {
243	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
244	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
245	        if (number != null) {
246	            fields.add("number=" + number);
247	        }
248	        fields.addAll(extra);
249	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
250	    }
251	
252	    private static BigDecimal scaled(BigDecimal amount) {
253	        return amount.setScale(2, RoundingMode.UNNECESSARY);
254	    }
255	}
