660	/**
661	 * The people kept on a sheet, in the order they were added. A name is stored without surrounding
662	 * spaces and is unique on its sheet regardless of case. An edit is made from a version of the
663	 * person; once someone else has saved the person since, it is refused.
664	 */
665	@Service
666	public class PersonService {
667	
668	    private static final int MAX_NAME = 100;
669	    private static final Set<String> GRADES = Set.of("A", "B", "C");
670	
671	    private final PersonRepository people;
672	    private final SheetService sheets;
673	    private final Audit audit;
674	
675	    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
676	        this.people = people;
677	        this.sheets = sheets;
678	        this.audit = audit;
679	    }
680	
681	    @Transactional(readOnly = true)
682	    public List<Person> list(String sheetId) {
683	        return people.findBySheetIdOrderByIdAsc(sheetId);
684	    }
685	
686	    @Transactional
687	    public Person add(String sheetId, String user, String name, String grade) {
688	        sheets.load(sheetId, user);
689	        String trimmed = name.trim();
690	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
691	            throw nameInUse();
692	        }
693	        Person person = people.save(new Person(sheetId, trimmed, grade));
694	        audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
695	        return person;
696	    }
697	
698	    /** A line of an import that breaks a rule: its number (from 1) and why. */
699	    public record ImportError(int line, String message) {
700	    }
701	
702	    /**
703	     * How many people an import added and how many existing ones it updated, or the lines that
704	     * stopped it (then nothing is changed).
705	     */
706	    public record ImportResult(int added, int updated, List<ImportError> errors) {
707	    }
708	
709	    /**
710	     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
711	     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
712	     * rule nothing is changed; otherwise, in order, a name already on the sheet has its grade
713	     * updated and any other name is added. Blank lines are skipped.
714	     */
715	    @Transactional
716	    public ImportResult importPeople(String sheetId, String user, String text) {
717	        String[] lines = text.split("\\r?\\n", -1);
718	        List<ImportError> errors = new ArrayList<>();
719	        List<String[]> rows = new ArrayList<>();
720	        Set<String> seen = new HashSet<>();
721	        for (int i = 0; i < lines.length; i++) {
722	            String line = lines[i];
723	            if (line.isBlank()) {
724	                continue;
725	            }
726	            int number = i + 1;
727	            int comma = line.lastIndexOf(',');
728	            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
729	            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
730	            String error = null;
731	            if (name.isEmpty()) {
732	                error = "Enter a name.";
733	            } else if (name.length() > MAX_NAME) {
734	                error = "The name is too long.";
735	            } else if (!GRADES.contains(grade)) {
736	                error = "The grade must be A, B or C.";
737	            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
738	                error = "That name is repeated in the import.";
739	            }
740	            if (error != null) {
741	                errors.add(new ImportError(number, error));
742	            } else {
743	                rows.add(new String[] {name, grade});
744	            }
745	        }
746	        if (!errors.isEmpty()) {
747	            return new ImportResult(0, 0, errors);
748	        }
749	        if (!rows.isEmpty()) {
750	            sheets.load(sheetId, user);
751	        }
752	        int added = 0;
753	        int updated = 0;
754	        for (String[] row : rows) {
755	            Optional<Person> existing = people.findFirstBySheetIdAndNameIgnoreCase(sheetId, row[0]);
756	            if (existing.isPresent()) {
757	                Person person = existing.get();
758	                person.setGrade(row[1]);
759	                person = people.saveAndFlush(person);
760	                audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
761	                updated++;
762	            } else {
763	                Person person = people.save(new Person(sheetId, row[0], row[1]));
764	                audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
765	                added++;
766	            }
767	        }
768	        return new ImportResult(added, updated, List.of());
769	    }
770	
771	    @Transactional
772	    public Person update(String sheetId, String user, Long personId, long version, String name, String grade) {
773	        Person person = people.findByIdAndSheetId(personId, sheetId)
774	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
775	        if (person.getVersion() != version) {
776	            throw changedMeanwhile();
777	        }
778	        String trimmed = name.trim();
779	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
780	            throw nameInUse();
781	        }
782	        person.setName(trimmed);
783	        person.setGrade(grade);
784	        try {
785	            person = people.saveAndFlush(person);
786	        } catch (OptimisticLockingFailureException e) {
787	            throw changedMeanwhile();
788	        }
789	        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
790	        return person;
791	    }
792	
793	    private static ResponseStatusException changedMeanwhile() {
794	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
795	    }
796	
797	    private static ResponseStatusException nameInUse() {
798	        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
799	    }
800	}
