907	        return rates.findBySheetIdOrderByGradeAscFromAsc(sheetId);
908	    }
909	
910	    /** The grade's rate in force on a date: the one with the latest from-date on or before it. */
911	    @Transactional(readOnly = true)
912	    public Optional<Rate> inForce(String sheetId, String grade, LocalDate date) {
913	        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
914	                .filter(rate -> rate.getFrom() == null || !rate.getFrom().isAfter(date))
915	                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())));
916	    }
