918	    @Transactional
919	    public Rate set(String sheetId, String user, String grade, LocalDate from, BigDecimal pct) {
920	        sheets.load(sheetId, user);
921	        BigDecimal scaled = pct.setScale(2, RoundingMode.UNNECESSARY);
922	        Rate rate = rates.findBySheetIdAndGrade(sheetId, grade).stream()
923	                .filter(r -> Objects.equals(r.getFrom(), from))
924	                .findFirst().orElse(null);
925	        if (rate == null) {
926	            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, scaled));
927	        } else {
928	            rate.setRate(scaled);
929	        }
930	        List<String> fields = new ArrayList<>(List.of("grade=" + rate.getGrade(), "rate=" + rate.getRate().toPlainString()));
931	        if (from != null) {
932	            fields.add("from=" + from);
933	        }
934	        audit.change("RATE_SET", sheetId, user, fields.toArray(String[]::new));
935	        return rate;
936	    }
